import random


def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    opp = [h[1] for h in history]
    me = [h[0] for h in history]
    opp_defects = 0
    for x in opp:
        if x == 'D':
            opp_defects += 1
    opp_coops = n - opp_defects
    defect_rate = opp_defects / n
    last_me, last_op = history[-1]

    # Detect streak of opponent defections at the tail
    streak = 0
    for i in range(n - 1, -1, -1):
        if opp[i] == 'D':
            streak += 1
        else:
            break

    # Detect streak of opponent cooperation at the tail
    cstreak = 0
    for i in range(n - 1, -1, -1):
        if opp[i] == 'C':
            cstreak += 1
        else:
            break

    # Detect alternating pattern in recent opponent moves
    alternating = False
    if n >= 6:
        tail = opp[-6:]
        ok = True
        for i in range(1, 6):
            if tail[i] == tail[i - 1]:
                ok = False
                break
        alternating = ok

    # --- Near the end of the match ---
    # If opponent has been extremely cooperative, defect on last few rounds for bonus.
    if n >= 96:
        if opp_defects == 0:
            return 'D'
        if opp_coops >= n - 2 and defect_rate < 0.15:
            return 'D'
        # Otherwise keep cooperating if partner is cooperative
        if last_op == 'C':
            return 'C'
        return 'D'

    # --- Pure cooperator handling ---
    if opp_defects == 0:
        # Long-run cooperative; small exploitation risk-free gain near end handled above.
        return 'C'

    # --- Chronic defector handling ---
    if defect_rate > 0.75 and streak >= 3:
        return 'D'

    # --- Alternating provocateur (D C D C ...) ---
    if alternating:
        # Predict next opponent move: mirror their next based on parity
        # If last was C, next likely D, so defect to avoid CD; if last D, next C, cooperate to get CC.
        if last_op == 'C':
            return 'D'
        else:
            return 'C'

    # --- Long opponent D streak: punish, but don't lock in forever ---
    if streak >= 3:
        # Probe occasionally to break mutual defection lock
        if rng.random() < 0.08:
            return 'C'
        return 'D'

    # --- Established mutual cooperation: preserve it ---
    if cstreak >= 3 and defect_rate < 0.3:
        # Only rare, very sparse exploitation to keep it robust
        if rng.random() < 0.04 and n < 90:
            return 'D'
        return 'C'

    # --- Opponent just defected ---
    if last_op == 'D':
        # Isolated defection in otherwise cooperative play: punish once, then forgive.
        if defect_rate < 0.25 and streak == 1:
            # Single-round retaliation then repair back to C next round.
            if last_me == 'D':
                # We already retaliated last round; return to cooperation to repair.
                return 'C'
            return 'D'
        # Moderate defector: retaliate but with forgiveness probability if they just cooperated
        if defect_rate < 0.5:
            if last_me == 'C':
                return 'D'
            # We already punished; give them a chance to reciprocate cooperation
            if rng.random() < 0.5:
                return 'C'
            return 'D'
        # Heavier defector: keep defecting, small probe
        if rng.random() < 0.1:
            return 'C'
        return 'D'

    # --- Opponent just cooperated ---
    # If we were punishing, return to restore mutual cooperation.
    if last_me == 'D':
        # Conciliatory repair: avoid endless retaliation cycles.
        return 'C'

    # Opponent cooperative, we cooperative: continue cooperating.
    return 'C'
